-- 011: Fix VARCHAR(36) to VARCHAR(64) on all ID columns
-- IDs generated by Descript (e.g., user_01a21877574687b55a0c899141e2a0ae) exceed VARCHAR(36)
-- This migration widens all primary/foreign key ID columns to VARCHAR(64)

-- users.id: requires dropping the v_neon_auth_controllers view first
DROP VIEW IF EXISTS public.v_neon_auth_controllers;

ALTER TABLE public.users ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.agents ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.agents ALTER COLUMN owner_id TYPE VARCHAR(64);
ALTER TABLE public.api_keys ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.api_keys ALTER COLUMN user_id TYPE VARCHAR(64);
ALTER TABLE public.credentials ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.credentials ALTER COLUMN agent_id TYPE VARCHAR(64);
ALTER TABLE public.audit_events ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.audit_events ALTER COLUMN agent_id TYPE VARCHAR(64);
ALTER TABLE public.auth_challenges ALTER COLUMN id TYPE VARCHAR(64);
ALTER TABLE public.auth_challenges ALTER COLUMN agent_id TYPE VARCHAR(64);

-- agents.user_id is a legacy column; owner_id is the canonical FK. Make user_id nullable.
ALTER TABLE public.agents ALTER COLUMN user_id DROP NOT NULL;

-- Recreate the Neon Auth integration view
CREATE OR REPLACE VIEW public.v_neon_auth_controllers AS
SELECT
    u.id              AS auth_user_id,
    u.email,
    u.name,
    u."createdAt"     AS auth_created_at,
    c.id              AS descript_user_id,
    c.organization
FROM neon_auth."user" u
LEFT JOIN public.users c ON lower(u.email) = lower(c.email::text);
